#!/usr/bin/env python3
"""Test hologram ownership and updates with in-memory Bukkit stubs, not a live client."""
import os,pathlib,subprocess,tempfile
root=pathlib.Path(__file__).resolve().parents[2]
src=root/'tools/elytrix-airdrop/src/ru/rooyzee/elytrixairdrop'
files={
'org/bukkit/event/Listener.java':'package org.bukkit.event; public interface Listener {}',
'org/bukkit/event/EventHandler.java':'package org.bukkit.event; import java.lang.annotation.*; @Retention(RetentionPolicy.RUNTIME) public @interface EventHandler {}',
'org/bukkit/event/server/PluginDisableEvent.java':'package org.bukkit.event.server; public class PluginDisableEvent {private Object p;public PluginDisableEvent(Object p){this.p=p;}public Object getPlugin(){return p;}}',
'org/bukkit/Bukkit.java':'package org.bukkit; public class Bukkit {public static Manager getPluginManager(){return new Manager();}public static class Manager {public void registerEvents(Object l,Object p){}}}',
'org/bukkit/Color.java':'package org.bukkit; public class Color {public int alpha; public static Color fromARGB(int a,int r,int g,int b){Color c=new Color();c.alpha=a;return c;}}',
'org/bukkit/Location.java':'package org.bukkit; public class Location implements Cloneable {public World w;public double x,y,z;public Location(World w,double x,double y,double z){this.w=w;this.x=x;this.y=y;this.z=z;} public World getWorld(){return w;}public int getBlockX(){return (int)Math.floor(x);}public int getBlockZ(){return (int)Math.floor(z);}public Location clone(){return new Location(w,x,y,z);} }',
'org/bukkit/World.java':'package org.bukkit; import org.bukkit.entity.TextDisplay; public class World {public boolean loaded=true;public int spawns;public TextDisplay last;public boolean isChunkLoaded(int x,int z){return loaded;}public <T> T spawn(Location p,Class<T> clazz){spawns++;last=new TextDisplay();last.position=p;return clazz.cast(last);} }',
'org/bukkit/entity/Display.java':'package org.bukkit.entity; public interface Display {enum Billboard {CENTER}}',
'org/bukkit/entity/TextDisplay.java':'''package org.bukkit.entity; import org.bukkit.*; public class TextDisplay {public boolean valid=true,persistent=true,background=true,shadow=true,seeThrough=true;public int alpha=-1,width;public String text;public Location position;public Display.Billboard billboard;public void setPersistent(boolean b){persistent=b;} public void setInvulnerable(boolean b){} public void setBillboard(Display.Billboard b){billboard=b;}public void setDefaultBackground(boolean b){background=b;} public void setBackgroundColor(Color c){alpha=c.alpha;}public void setShadowed(boolean b){shadow=b;}public void setSeeThrough(boolean b){seeThrough=b;}public void setTextOpacity(byte b){}public void setLineWidth(int w){width=w;}public void setText(String t){text=t;}public boolean isValid(){return valid;}public void remove(){valid=false;}public boolean teleport(Location l){position=l;return true;}}''',
'ru/rooyzee/elytrixairdrop/utils/ColorUtil.java':'package ru.rooyzee.elytrixairdrop.utils; public class ColorUtil {public static String colorize(String s){return s;}}',
'ru/rooyzee/elytrixairdrop/airdrops/Airdrop.java':'package ru.rooyzee.elytrixairdrop.airdrops; public class Airdrop {public String id;public Airdrop(String id){this.id=id;}public String getId(){return id;}}',
'ru/rooyzee/elytrixairdrop/airdrops/ActiveAirdrop.java':'package ru.rooyzee.elytrixairdrop.airdrops; public class ActiveAirdrop {public String name;public Airdrop type;public ActiveAirdrop(String n,String t){name=n;type=new Airdrop(t);}public String getHologramName(){return name;}public Airdrop getType(){return type;} }',
'ru/rooyzee/elytrixairdrop/airdrops/types/ActiveFireAirdrop.java':'package ru.rooyzee.elytrixairdrop.airdrops.types; import ru.rooyzee.elytrixairdrop.airdrops.ActiveAirdrop; public class ActiveFireAirdrop extends ActiveAirdrop {public String phase="COOLING"; public ActiveFireAirdrop(String n){super(n,"fire");}public String hologramPhase(){return phase;} }',
'ru/rooyzee/elytrixairdrop/patch/EventBar.java':'package ru.rooyzee.elytrixairdrop.patch; import ru.rooyzee.elytrixairdrop.airdrops.ActiveAirdrop; public class EventBar {public static String stage(ActiveAirdrop a){return "Остывание";} }',
'ru/rooyzee/elytrixairdrop/Main.java':'''package ru.rooyzee.elytrixairdrop; import java.util.logging.*; import ru.rooyzee.elytrixairdrop.airdrops.*; import ru.rooyzee.elytrixairdrop.managers.*; public class Main {public static Main instance;public HologramManager holograms;public Manager manager=new Manager();public ConfigManager config=new ConfigManager();public Main(){instance=this;}public static Main getInstance(){return instance;}public HologramManager getHologramManager(){return holograms;}public Manager getAirdropManager(){return manager;}public ConfigManager getConfigManager(){return config;}public Logger getLogger(){return Logger.getAnonymousLogger();}public static class Manager {public ActiveAirdrop active;public ActiveAirdrop getActive(){return active;}}public static class ConfigManager {public Config config=new Config();public Config getConfig(){return config;}}public static class Config {public boolean custom;public boolean getBoolean(String path,boolean def){return custom;}}}''',
'TestManager.java':'''import java.util.*; import org.bukkit.*; import org.bukkit.entity.*; import org.bukkit.event.server.*; import ru.rooyzee.elytrixairdrop.*; import ru.rooyzee.elytrixairdrop.managers.*; import ru.rooyzee.elytrixairdrop.airdrops.types.*; public class TestManager {static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[] args){Main p=new Main();World w=new World();HologramManager m=new HologramManager(p);p.holograms=m;String name=m.createHologram(new Location(w,2,64,2),List.of("loading"));TextDisplay d=w.last;check(!d.background&&d.alpha==0&&!d.shadow&&!d.persistent&&d.billboard==Display.Billboard.CENTER,"transparent display");ActiveFireAirdrop a=new ActiveFireAirdrop(name);p.manager.active=a;m.updateHologram(name,List.of("old config"));check(d.text.contains("обсидиан")&&d.text.contains("Сундук внутри")&&!d.text.contains("old config"),"modern fire text");m.moveHologram(name,new Location(w,6,73,7));check(d.position.y==73&&d.position.x==6,"move");p.config.config.custom=true;m.updateHologram(name,List.of("custom"));check(d.text.equals("custom"),"custom opt-out");p.config.config.custom=false;d.valid=false;w.loaded=false;int n=w.spawns;m.updateHologram(name,List.of("old"));check(w.spawns==n,"no forced chunk load");w.loaded=true;m.updateHologram(name,List.of("old"));check(w.spawns==n+1&&w.last.text.contains("обсидиан"),"respawn on chunk load");TextDisplay main=w.last;HologramManager.createSky("shulker",new Location(w,3,65,3),List.of("open"));TextDisplay sky=w.last;check(sky.text.equals("open")&&sky.alpha==0,"sky hologram");m.updateHologram("shulker",List.of("opened"));check(sky.text.equals("opened"),"sky update");m.removeHologram("shulker");check(!sky.valid,"sky cleanup");m.disable(new PluginDisableEvent(p));check(!main.valid,"disable cleanup");System.out.println("Hologram stub test: transparent, fire text, movement, chunk reload, sky and cleanup OK");}}'''
}
java=os.environ['JAVA'];ecj=os.environ['ECJ']
with tempfile.TemporaryDirectory() as tmp:
 p=pathlib.Path(tmp)
 for name,content in files.items():
  f=p/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(content)
 out=p/'classes';out.mkdir()
 sources=[str(p/x) for x in files]+[str(src/'managers/HologramManager.java'),str(src/'patch/HologramText.java')]
 subprocess.run([java,'-jar',ecj,'-21','-proc:none','-nowarn','-d',str(out),*sources],check=True)
 subprocess.run([java,'-Xverify:all','-cp',str(out),'TestManager'],check=True)
